  async function portalAdminList(){if(!window.devilPortal||norm(api.user?.email)!=='divarebel on gmail com')return;const select=$('#portalAdminProfile'),status=$('#portalAdminStatus');try{const clients=await window.devilPortal.loadAdmin();$('#portalAdminClients').innerHTML=clients.map(c=>'<article class="card"><b>'+esc(c.profileName)+'</b><p>'+esc(c.email)+' &middot; '+(c.active?'Ativa':'Inativa')+' &middot; '+(c.hasContent?'Com publica&ccedil;&otilde;es':'Sem publica&ccedil;&otilde;es')+'</p></article>').join('')||'<p class="no-data">Nenhum acesso cadastrado ainda.</p>';status.textContent='Lista atualizada.'}catch(e){status.textContent=e.message||'Falha ao carregar clientes.'}}
  function portalAdminProfile(){const c=app().clients.find(x=>x.id===$('#portalAdminProfile')?.value);if(c&&!$('#portalAdminName').value)$('#portalAdminName').value=c.name||c.profile?.name||'';return c}
  async function portalAdminSave(){const c=portalAdminProfile(),email=$('#portalAdminEmail').value.trim().toLowerCase(),name=$('#portalAdminName').value.trim(),status=$('#portalAdminStatus');if(!c||!email||!name){status.textContent='Selecione o perfil e informe e-mail e nome.';return}try{const scheduleUrl=$('#portalClickUpSchedule').value.trim(),ideasUrl=$('#portalClickUpIdeas').value.trim();await window.devilPortal.request('portalAdminSaveClient',{email,clientId:c.id,profileName:name,clickupScheduleUrl:scheduleUrl,clickupIdeasUrl:ideasUrl});c.clickupScheduleUrl=scheduleUrl;c.clickupIdeasUrl=ideasUrl;save();status.textContent='Acesso e listas salvos para '+email;await portalAdminList();if($('#portalClickUpSchedule').value.trim()||$('#portalClickUpIdeas').value.trim())await portalAdminSyncNow()}catch(e){status.textContent=e.message||'N?o foi poss?vel salvar.'}}
    async function portalAdminLoad(){const email=$('#portalAdminEmail').value.trim().toLowerCase();if(!email)return;try{const r=await window.devilPortal.request('portalAdminGetClient',{email});$('#portalAdminName').value=r.client.profileName;$('#portalAdminProfile').value=r.client.clientId;$('#portalClickUpSchedule').value=r.client.clickupScheduleUrl||'';$('#portalClickUpIdeas').value=r.client.clickupIdeasUrl||'';const loadedProfile=portalAdminProfile();if(loadedProfile){loadedProfile.clickupScheduleUrl=r.client.clickupScheduleUrl||'';loadedProfile.clickupIdeasUrl=r.client.clickupIdeasUrl||'';save()}$('#portalAdminStatus').textContent='Cliente carregada: '+email;window.__portalAdminLoaded=r.data}catch(e){$('#portalAdminStatus').textContent=e.message||'Cliente não encontrada.'}}
  async function imageData(assetId){if(!assetId)return'';const url=await api.getFileUrl(assetId);const blob=await(await fetch(url)).blob();const img=await createImageBitmap(blob);const canvas=document.createElement('canvas'),ratio=Math.min(1,720/img.width,900/img.height);canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.72)}
  async function portalAdminPublish(){const c=portalAdminProfile(),email=$('#portalAdminEmail').value.trim().toLowerCase(),status=$('#portalAdminStatus');if(!c||!email){status.textContent='Selecione perfil e cliente.';return}status.textContent='Preparando o material deste perfil...';try{const ideas=(app().instagramIdeas||[]).filter(x=>x.clientId===c.id).map(x=>({id:x.id,title:x.title,caption:x.caption||'',sourceUrl:x.sourceUrl||'',collection:x.collection||'',status:x.status||'new'}));const approvals=[];for(const p of (app().approvals||[]).filter(x=>x.clientId===c.id)){const slides=[];for(const sl of p.slides||[])slides.push({headline:sl.headline||'',text:sl.text||'',imageDataUrl:await imageData(sl.assetId),comments:sl.comments||[]});approvals.push({id:p.id,title:p.title,format:p.format,profileName:c.profile?.name||c.name,caption:p.caption||p.title,approved:!!p.approved,comments:p.comments||[],slides})}const portalData={clientId:c.id,profileName:$('#portalAdminName').value.trim()||c.name,ideas,approvals};const result=await window.devilPortal.request('portalAdminSaveContent',{email,portalData});status.textContent='Publicado: '+result.ideaCount+' ideias e '+result.approvalCount+' conte&uacute;dos.'}catch(e){status.textContent=e.message||'Falha ao publicar.'}}
  async function portalAdminSyncNow(){const email=$('#portalAdminEmail').value.trim().toLowerCase(),status=$('#portalAdminStatus');if(!email){status.textContent='Informe o e-mail da cliente.';return}try{const r=await window.devilPortal.request('portalAdminSyncClickUp',{email});status.textContent='ClickUp sincronizado: '+r.approvalCount+' publica??es e '+r.ideaCount+' ideias. Clique em Publicar para atualizar o espa?o da cliente.'}catch(e){status.textContent=e.message||'N?o consegui sincronizar as listas do ClickUp.'}}
  async function portalAdminPreview(){const email=$('#portalAdminEmail').value.trim().toLowerCase();if(!email)return;try{const r=await window.devilPortal.request('portalAdminGetClient',{email});const box=$('#portalAdminPreviewBox');window.devilPortal.render(r.data,box,true);box.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){$('#portalAdminStatus').textContent=e.message||'Não foi possível abrir a prévia.'}}
