  async function importInstagram(){const input=$('#instagramExport'),status=$('#ideasStatus'),file=input?.files?.[0];if(!file){status.textContent='Selecione o arquivo ZIP, JSON ou HTML exportado do Instagram.';return}status.textContent='Lendo as coleções salvas…';try{let text;if(/\.zip$/i.test(file.name)||file.type==='application/zip')text=await zipText(file);else text=await file.text();const rows=/\.html?$/i.test(file.name)||/^\s*</.test(text)?parseInstagramHtml(text):parseInstagramJson(text);if(!rows.length)throw Error('O arquivo foi lido, mas não encontrei referências em coleções. Exporte a seção Saved em JSON ou HTML.');const merged=new Map((app().instagramIdeas||[]).map(x=>[x.id||x.collection+'|'+x.sourceUrl,x]));for(const row of rows){const key=row.id||row.collection+'|'+row.sourceUrl,prior=merged.get(key);merged.set(key,{...(prior||{}),...row,clientId:prior?.clientId||row.clientId||'',clientName:prior?.clientName||row.clientName||''})}app().instagramIdeas=[...merged.values()];save();renderIdeas();const unmatched=rows.filter(x=>!x.clientId).length;status.textContent=rows.length+' referências importadas. '+(unmatched?unmatched+' ficaram sem cliente correspondente e não aparecem nos perfis.':'Todas foram associadas a uma cliente pela coleção.');input.value=''}catch(e){status.textContent=e.message||'Não consegui ler o arquivo de coleções.'}}
