  function normalizeChoice(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
  function findTypedChoice(s){const n=normalizeChoice(s);if(chat.step==='format'){if(/\b(stories|story|stories)\b/.test(n))return formatChoices[0];if(/\bcarrossel\b/.test(n))return formatChoices[1];if(/\b(reel|reels|video)\b/.test(n))return formatChoices[2];if(/\b(post|estatico|feed)\b/.test(n))return formatChoices[3];if(/\blive\b/.test(n))return formatChoices[4]}if(chat.step==='goal'){if(/vender|venda|lead|captar/.test(n))return goalChoices[4];if(/autoridade/.test(n))return goalChoices[2];if(/conexao|relacionamento/.test(n))return goalChoices[1];if(/engaj|conversa|resposta/.test(n))return goalChoices[3];if(/emoc/.test(n))return goalChoices[5];if(/atrair|crescer|publico|audiencia/.test(n))return goalChoices[0]}if(chat.step==='stage'){if(/descoberta|frio|topo/.test(n))return stageChoices[0];if(/consideracao|morno|meio/.test(n))return stageChoices[1];if(/decisao|decidir|fundo/.test(n))return stageChoices[2];if(/recuperacao|retomar|recuperar/.test(n))return stageChoices[3]}if(chat.step==='emotion'){const i=emotionChoices.findIndex(x=>normalizeChoice(x.label)===n);if(i>=0)return emotionChoices[i];if(/outra|outro|personalizada/.test(n))return emotionChoices[5]}return null}
