  async function createQuick(which){const isSos=which==='sos',prefix=isSos?'sos':'analysis',client=(app().clients||[]).find(c=>c.id===$('#'+prefix+'Profile').value)||api.activeClient(),text=$('#'+prefix+'Text').value.trim(),kind=isSos?$('#sosType').value:$('#analysisType').value,status=$('#'+prefix+'Status'),button=$(isSos?'#runSos':'#runAnalysis'),out=$(isSos?'#sosOutput':'#analysisOutput');if(!api.user||!client){status.textContent='Entre na conta e escolha um perfil.';return}if(!text&&!$('#'+prefix+'Text').dataset.image){status.textContent='Adicione contexto por texto, áudio ou arquivo.';return}button.disabled=true;status.textContent='Preparando sua resposta...';try{if(!isSos&&$('#analysisText').dataset.image){const resp=await fetch(api.api,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({action:'analyzeDesign',requestId:api.uid(),idToken:await api.user.getIdToken(),imageDataUrl:$('#analysisText').dataset.image,context:{analysisType:kind,objective:text,handle:client.profile?.instagramHandle||'',profile:client.profile,brandIdentity:client.branding}})}),d=await resp.json();if(!d.ok)throw Error(d.error);out.innerHTML='<h3>'+esc(d.review.summary)+'</h3><p>'+esc(d.review.legibility)+' '+esc(d.review.hierarchy)+' '+esc(d.review.contrast)+' '+esc(d.review.objectiveFit)+'</p><ul>'+d.review.actions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';const summary=[d.review.summary,d.review.legibility,d.review.hierarchy,d.review.contrast,d.review.objectiveFit,...d.review.actions].join('\n');app().analysisHistory.unshift({id:api.uid(),type:kind,text:summary,requestText:text,clientId:client.id,createdAt:new Date().toISOString()});historyRecord({kind:'analysis',title:kind,summary,requestText:text,clientId:client.id});renderHistory('analysis')}else{const prompt=isSos?'SOS — '+kind+'. Resolva diretamente, com contexto e voz do perfil. Não faça uma sequência de stories. Pedido: '+text:'ANÁLISE — '+kind+'. Entregue diagnóstico, prioridades e próximos ajustes práticos. Não invente métricas. Contexto: '+text;const input=api.copyInput(client,null,prompt,'');input.storyCount=3;input.objective=prompt;input.productionBrief='Este é um pedido do menu '+(isSos?'SOS':'Análises')+'. Responda a tarefa com precisão e sem citar a plataforma nem o provedor. '+($('#'+prefix+'Text').dataset.imageName||'');const episode=await api.requestCopy(input,await api.user.getIdToken());const summary=episode.theme+'\n'+(episode.stories||[]).map(x=>[x.headline,x.text].filter(Boolean).join('\n')).join('\n');out.innerHTML='<h3>'+esc(episode.theme)+'</h3>'+(episode.stories||[]).map(x=>'<h3>'+esc(x.headline||x.point)+'</h3><p>'+esc(x.text)+'</p>').join('');const hist=isSos?'sosHistory':'analysisHistory';app()[hist].unshift({id:api.uid(),type:kind,text:summary,requestText:text,clientId:client.id,createdAt:new Date().toISOString()});historyRecord({kind:isSos?'sos':'analysis',title:kind,summary,requestText:text,clientId:client.id});renderHistory(isSos?'sos':'analysis')}out.hidden=false;save();status.textContent='Pronto. Salvo na sua conta.'}catch(e){status.textContent='Não consegui concluir. Revise o contexto e tente de novo.';console.error('DEVIL '+which,e)}finally{button.disabled=false}}
  $('#runSos').onclick=()=>createQuick('sos');$('#runAnalysis').onclick=()=>createQuick('analysis');
  setInterval(()=>{const before=app().history.length;pruneHistory();if(before!==app().history.length)renderUnifiedHistory()},60*60*1000);
  const clientsObserver=new MutationObserver(()=>{renderMedia();renderBrain()});if($('#clientList'))clientsObserver.observe($('#clientList'),{childList:true,subtree:true});
  async function syncInstagramSeed(){const user=api.user,uid=user?.uid;if(!uid)return;if(norm(user.email)!=='divarebel on gmail com'){const status=$('#ideasStatus');if(status)status.textContent='As pastas pessoais ficam no login @divarebel.on; as cole\u00e7\u00f5es de clientes ficam separadas por perfil.';return}if(uid===instagramSeedLoadedUid){renderIdeas();return}instagramSeedLoadedUid=uid;const status=$('#ideasStatus');if(status)status.textContent='Sincronizando os salvos do Instagram...';try{const url=new URL('../devil-conteudos/instagram-ideas.json',location.href),response=await fetch(url,{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const seed=await response.json();if(!Array.isArray(seed))throw Error('Formato inv\u00e1lido do arquivo de colecoes.');const rows=new Map((app().instagramIdeas||[]).map(x=>[x.id||x.collection+'|'+x.sourceUrl,x]));let changed=false;for(const item of seed){const prior=rows.get(item.id),ownerCollection=['formatos','minha visao'].includes(norm(item.collection)),client=ownerCollection?null:assignClient(item.collection),label=String(item.collection||'').replace(/^cliente\s*:\s*/i,'').trim(),clientId=ownerCollection?'__owner__':(prior?.clientId||client?.id||('__client__'+norm(label).replace(/\s+/g,'-'))),clientName=ownerCollection?'@divarebel.on':(client?.name||label||prior?.clientName||''),next={...item,clientId,clientName,savedAt:prior?.savedAt||''};if(!prior||prior.clientId!==clientId||prior.clientName!==clientName){rows.set(item.id,{...(prior||{}),...next});changed=true}}if(changed){app().instagramIdeas=[...rows.values()];save()}renderIdeas();const formats=seed.filter(x=>norm(x.collection)==='formatos').length,personal=seed.filter(x=>norm(x.collection)==='minha visao').length;if(status)status.textContent=seed.length+' refer\u00eancias sincronizadas: '+formats+' em FORMATOS, '+personal+' em MINHA VISAO e cole\u00e7\u00f5es de clientes associadas aos perfis.'}catch(error){instagramSeedLoadedUid='';if(status)status.textContent='N?o consegui carregar os salvos. Abra o Banco de ideias para tentar novamente. ('+String(error.message||error)+')';console.warn('DEVIL Instagram saved collections seed unavailable',error)}}
  window.addEventListener('devil:data-ready',()=>{mergeDuplicates();render();syncInstagramSeed()});const seedSyncTimer=setInterval(()=>{if(api.user?.uid&&$('#saveStatus')?.textContent.includes('Salvo na sua conta')){clearInterval(seedSyncTimer);syncInstagramSeed()}},300);
  const storyList=$('#storyList');if(storyList){new MutationObserver(()=>requestAnimationFrame(()=>{fitText();renderClarification()})).observe(storyList,{childList:true,subtree:true,characterData:true});storyList.addEventListener('input',()=>requestAnimationFrame(fitText))}
  const syncReady=new MutationObserver(()=>{if($('#accountEmail')?.textContent&&$('#saveStatus')?.textContent.includes('Salvo na sua conta')){syncReady.disconnect();mergeDuplicates();render()}});if($('#saveStatus'))syncReady.observe($('#saveStatus'),{childList:true,characterData:true,subtree:true});
  nav.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;setTimeout(()=>{const t={templates:'Templates Canva',brain:'Segundo cérebro',sos:'SOS',analysis:'Análises',settings:'Configurações'};if(t[b.dataset.view])$('#pageTitle').textContent=t[b.dataset.view]},0)});
  const fields=['sosProfile','analysisProfile'];fields.forEach(id=>$('#'+id).onchange=()=>{const c=app().clients.find(x=>x.id===$('#'+id).value);if(c)app().activeClientId=c.id;save()});
  render();
